"""Exact approved D3 current predicates, old true runtime receipts and one new HTTP refusal."""
from pathlib import Path
from hashlib import sha256
from datetime import datetime,timezone
import ast,os,json,tomllib,xml.etree.ElementTree as E

def test_exact_d3_session_and_external_header_receipts():
    path=Path(os.environ['NOMOSMART_CURRENT_D3_AUTH_SCOPE']);scope=json.loads(path.read_bytes());assert scope['kind']=='CHG388_EXACT_D3_AUTH_REUSE'and not scope['closed']and datetime.now(timezone.utc)<datetime.fromisoformat(scope['deadline']);assert scope['operation_uuid']=='24c50237-b9ef-4dc7-b732-13e60933c5cf';root=Path(__file__).resolve().parents[2];assert scope['source_root']==str(root)
    from scripts.public_source_inventory import PublicSourceInventory
    inv=PublicSourceInventory.load(root,path.parent/'source-inventory.json',expected_sha256=scope['source_inventory_sha256']);approval=json.loads(inv.read('docs/CHG-388-CONTINUATION-APPROVAL.json')[0]);assert approval['gate_4']=='APPROVED'and approval['human_answers']['D3'].startswith('核准 D3');assert sha256(inv.read('docs/CHG-388-CONTINUATION-DECISIONS.md')[0]).hexdigest()==approval['approved_markdown_sha256']
    def read(n):
        p=Path(scope['materials'][n]['path']);assert p.is_absolute()and p.resolve()==p and not p.is_symlink();body=p.read_bytes();assert sha256(body).hexdigest()==scope['materials'][n]['sha256'];return body
    def load(n):return json.loads(read(n))
    maintenance=load('maintenance_qualification');oldrow=next(x for x in maintenance['qualified']if x['case'].endswith('::test_naturally_expired_issued_session_is_rejected'));assert oldrow['junit_sha256']==scope['materials']['natural_expiry_xml']['sha256'];allapp={n:h for n,h in oldrow['all_unchanged_dependencies'].items()if n.startswith('backend/app/')};assert all(sha256(inv.read(n)[0]).hexdigest()==h for n,h in allapp.items()if n!='backend/app/security/session_auth.py');assert sha256(read('old_session_source')).hexdigest()==allapp['backend/app/security/session_auth.py'];assert sha256(inv.read('backend/app/core/config.py')[0]).hexdigest()==oldrow['config_retirement_only_AST_review']['current_sha256'];assert sha256(inv.read('backend/app/security/auth.py')[0]).hexdigest()==oldrow['auth_unused_function_only_AST_review']['current_sha256']
    old=ast.parse(read('old_session_source').decode());new=ast.parse(inv.read('backend/app/security/session_auth.py')[0].decode());oldf={n.name:n for n in old.body if isinstance(n,ast.FunctionDef)};newf={n.name:n for n in new.body if isinstance(n,ast.FunctionDef)};assert set(newf)==set(oldf)|{'validate_session_row'}
    dump=lambda n:ast.dump(n,include_attributes=False)
    assert all(dump(n)==dump(newf[name])for name,n in oldf.items()if name!='validate_session_secret');oldbody=oldf['validate_session_secret'].body;secret=newf['validate_session_secret'].body;row=newf['validate_session_row'].body;assert [dump(n)for n in oldbody[1:5]]==[dump(n)for n in secret[1:5]];assert [dump(n)for n in oldbody[5:]]==[dump(n)for n in row[1:]];assert isinstance(secret[5],ast.Return)and ast.unparse(secret[5].value)=='validate_session_row(settings, session, row)';assert len(secret)==6
    execution=load('source387');assert execution['files']['backend/app/security/session_auth.py']['sha256']==sha256(inv.read('backend/app/security/session_auth.py')[0]).hexdigest()
    # Immutable XML observations, including the failed earlier expiry observation.
    natural=list(E.fromstring(read('natural_expiry_xml')).iter('testcase'));assert len(natural)==1 and natural[0].get('name')=='test_naturally_expired_issued_session_is_rejected'and not list(natural[0]);denials=list(E.fromstring(read('revocation_xml')).iter('testcase'));byname={x.get('name'):x for x in denials};assert not list(byname['test_revoked_real_session_is_rejected'])and not list(byname['test_disabled_real_user_is_rejected']);assert any(c.tag in{'failure','error'}for c in byname['test_naturally_expired_issued_session_is_rejected']);disabled=list(E.fromstring(read('disabled_api_xml')).iter('testcase'));assert any(x.get('name')=='test_current_disabled_directory_user_cannot_login_and_old_session_is_revoked'and not list(x)for x in disabled)
    ledger=load('ledger')
    for name in ['test_naturally_expired_issued_session_is_rejected','test_revoked_real_session_is_rejected','test_current_disabled_directory_user_cannot_login_and_old_session_is_revoked']:
        r=next(x for x in ledger['rows']if x['case'].split('::')[-1]==name);assert r['count_as_current_pass']and sha256(inv.read(r['case'].split('::')[0])[0]).hexdigest()==r['test_module_sha256']
    # Record the precise dependency difference rather than claiming unchanged locks.
    project=tomllib.loads(read('old_project').decode());current=tomllib.loads(inv.read('backend/pyproject.toml')[0].decode());assert project['project']['version']=='0.2.0'and current['project']['version']=='0.2.3';current['project']['version']=project['project']['version'];assert current==project;assert sha256(read('old_project')).hexdigest()==oldrow['all_unchanged_dependencies']['backend/pyproject.toml'];assert sha256(read('old_lock')).hexdigest()==oldrow['all_unchanged_dependencies']['backend/uv.lock'];oldlock=tomllib.loads(read('old_lock').decode());newlock=tomllib.loads(inv.read('backend/uv.lock')[0].decode());oa={x['name']:x for x in oldlock['package']};na={x['name']:x for x in newlock['package']};assert {n for n in set(oa)|set(na)if oa.get(n)!=na.get(n)}=={'nomosmart-backend','pyasn1'};assert oa['pyasn1']['version']=='0.6.4'and na['pyasn1']['version']=='0.6.5';assert {k for k in oa['pyasn1']if oa['pyasn1'][k]!=na['pyasn1'][k]}=={'version','sdist','wheels'};na['nomosmart-backend']['version']=oa['nomosmart-backend']['version'];na['pyasn1'].update(oa['pyasn1']);assert oldlock==newlock
    query=load('D2_intent');assert query['original_business_tables_restored']and query['normal_session_cleanup']and len(query['versions'])==139 and query['logout_status']=={'owner':204,'outsider':204,'viewer':204};tests=list(E.fromstring(read('D2_XML')).iter('testcase'));assert len(tests)==4 and all(not list(x)for x in tests)
    runtime=load('new_header');assert runtime['actual_status']==401 and runtime['actual_error_code']=='authentication_required'and runtime['session_table_unchanged']and runtime['no_session_cookie_issued'];assert runtime['actual_public_idle_timeout_seconds']==1800 and runtime['actual_public_absolute_timeout_seconds']is None;assert load('new_header_execution')['actual_exit']==0;assert load('new_header_cleanup')['child_and_foreground_parent_actually_reaped'];assert load('new_header_API_owner')['source_root']==load('new_header_scope')['source_root']
    (path.parent/'result.json').write_text(json.dumps({'operation_uuid':scope['operation_uuid'],'proposal_id':'C388-2631936d5b2f','original_oldKC3second_token_method_PASS':False,'current_external_bearer_request_status':401,'one_new_anonymous_HTTP_predicate_no_login':True,'natural30minute_expiry_revocation_disabled_raw_receipts_reused':True,'old_failed_natural_expiry_observation_preserved':True,'session_secret_lookup_and_state_body_AST_preserved':True,'all_other_app_dependencies_from_qualified_source_exact':True,'backend_metadata_version_only_and_pyasn1_0_6_4_to_0_6_5_explicit':True,'actual_D2three_LDAP_sessions_confirm_current_dependency_path':True,'new_30minute_wait_or_IdP_or_JWT_signing_or_models':0,'coverage_hits_for_changed_files_reused':0,'whole_suite_or_coverage_or_release_PASS':False,'actual_materials':scope['materials']},indent=2))
